(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04-t*0.5)*8+Math.cos((y+w1y)*0.035+t*0.45)*6;
  const w2y = Math.cos((y+w1y)*0.04+t*0.55)*8+Math.sin((x+w1x)*0.03-t*0.4)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3)*40,0.14,1.3,0.7],
    [400+Math.cos(t*0.45+2)*70,200+Math.sin(t*0.65+4)*50,0.11,2.1,0.85]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp,wt]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*wt;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*wt;
    harm+=Math.sin(d*f*1.3-t*sp*0.8+0.7)*wt*0.5;
  }
  const act=aS/6,inh=iS/6,har=harm/6;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3+Math.sin(sx*0.08+Math.sin(sy*0.06+t)*0.5+t*1.5)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35+(Math.sin(dist*0.07+ang*2-t*0.9)+Math.sin(dist*0.03-ang*5+t*1.8))*0.2;
  const grain=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.7)*0.12;
  const raw=act-inh*0.7+bg*0.3+spiral+har*0.4+grain;
  const r1=Math.tanh(raw*2.2);
  const r2=Math.tanh(r1*1.5+Math.sin(r1*3+t)*0.3);
  const reaction=Math.tanh(r2*1.8);
  const fineScale=0.22,fineT=1.7;
  const fRaw=Math.sin(sx*fineScale+t*fineT)*Math.sin(sy*fineScale-t*fineT*0.8)+Math.sin((sx+sy)*fineScale*0.7+t*fineT*1.3)*0.4;
  const fineR=Math.tanh(fRaw*2)*0.2;
  const combined=reaction*0.82+fineR*0.18;
  const v=combined*0.5+0.5;
  const pal=[[5,10,52],[10,38,88],[16,75,118],[22,125,135],[60,165,125],[140,190,90],[195,185,70],[215,145,55],[200,95,55],[165,55,65],[115,30,65],[60,15,48],[25,8,42],[5,10,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=(1-Math.cos(f*Math.PI))*0.5;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const eStr=Math.abs(reaction);
  const edgeGlow=eStr>0.6?1.08+eStr*0.12:0.92+eStr*0.15;
  const breath=0.97+Math.sin(t*0.4)*0.03;
  const shift=Math.sin(ang*2+t*0.3)*0.04;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*(1+shift))*lum*edgeGlow*breath)|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf))*lum*edgeGlow*breath)|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*(1-shift))*lum*edgeGlow*breath)|0
  ];
}
